<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;require ROOT.'/includes/panel.php';?><h1>Auditoria.</h1><p class="muted">Últimos 300 registros. Logs não podem ser editados pelo painel.</p><div class="table-wrap"><table><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Detalhes</th></tr><?php foreach(rows('SELECT a.*,u.email FROM audit a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 300') as $a):?><tr><td class="no-wrap"><?=e($a['created_at'])?></td><td><?=e($a['email']??'Sistema')?></td><td><?=e($a['action'])?></td><td><?=e($a['details'])?></td></tr><?php endforeach;?></table></div><?php require ROOT.'/includes/endpanel.php';?>
